<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">测距</text><text class="nav-icon empty"> </text></view></view><view class="content"><view class="measure-area"><view class="measure-line" :style="{ width: lineLength + 'px' }"></view><text class="measure-value">{{ distance }} cm</text></view><view class="measure-btn" @click="measure"><text>测量</text></view><view class="measure-tip">将手机对准目标物体</text></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const distance = ref(0); const lineLength = ref(100)
function measure() { distance.value = Math.floor(Math.random() * 100 + 10); lineLength.value = distance.value * 3 }
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#2d3436}.custom-nav{background:linear-gradient(135deg,#00b894,#00cec9);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-icon.empty{visibility:hidden}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:40rpx}.measure-area{height:400rpx;background:rgba(255,255,255,0.1);border-radius:20rpx;display:flex;flex-direction:column;align-items:center;justify-content:center;margin-bottom:32rpx}.measure-line{height:4rpx;background:#00cec9;margin-bottom:24rpx;transition:width 0.3s}.measure-value{font-size:48rpx;color:#00cec9;font-weight:700}.measure-btn{width:80%;background:linear-gradient(135deg,#00b894,#00cec9);border-radius:16rpx;padding:28rpx;text-align:center;margin-bottom:24rpx}.measure-btn text{font-size:32rpx;color:#fff;font-weight:600}.measure-tip{text-align:center;font-size:24rpx;color:rgba(255,255,255,0.5)}</style>